     <script>
       const params = new URLSearchParams(location.search);
       const state = {
         v: params.get("v") || "a",
         gon: params.get("gon") || "0",
         bolap: params.get("bolap") || "0",
         mau: params.get("mau") || "xam",
         kho: params.get("kho") || "desktop",
         tt: params.get("tt") || "du-lieu",
         uu: params.get("uu") || "0",
       };
       Object.assign(document.body.dataset, {
         v: state.v, gon: state.gon, bolap: state.bolap, mau: state.mau, kho: state.kho, tt: state.tt, uu: state.uu,
       });
       if (params.has("frame")) document.body.dataset.frame = "1";
       if (state.kieu === "midnight") document.documentElement.classList.add("dark-mode");

       const labels = {
         tt: { "du-lieu": "Có dữ liệu", "dang-tai": "Đang tải", rong: "Rỗng", loi: "Lỗi" },
       };
       const linkTo = (changes) => `?${new URLSearchParams({ ...state, ...changes })}`;
       function updateLinks() {
         document.querySelectorAll("[data-wf-param]").forEach((set) => {
           set.querySelectorAll("a").forEach((link) => {
             const key = set.dataset.wfParam;
             link.href = linkTo({ [key]: link.dataset.value });
             if (state[key] === link.dataset.value) {
               link.setAttribute("aria-current", "page");
               const label = document.querySelector(`[data-wf-current="${key}"]`);
               if (label) label.textContent = labels[key][link.dataset.value] || link.textContent.trim();
             } else {
               link.removeAttribute("aria-current");
             }
           });
         });
         document.querySelectorAll("[data-wf-toggle]").forEach((toggle) => {
           const key = toggle.dataset.wfToggle;
           const on = state[key] === toggle.dataset.on;
           toggle.setAttribute(toggle.getAttribute("role") === "switch" ? "aria-checked" : "aria-pressed", String(on));
           toggle.href = linkTo({ [key]: on ? toggle.dataset.off : toggle.dataset.on });
         });
       }
       updateLinks();

       const reason = document.querySelector("[data-wf-reason]");
       reason.open = state.uu === "1";
       reason.addEventListener("toggle", () => {
         state.uu = reason.open ? "1" : "0";
         history.replaceState(null, "", linkTo({}));
         updateLinks();
       });

       document.querySelectorAll(".wf-menu").forEach((menu) => {
         menu.addEventListener("toggle", () => {
           if (!menu.open) return;
           document.querySelectorAll(".wf-menu").forEach((other) => { if (other !== menu) other.open = false; });
         });
       });
       document.addEventListener("click", (event) => {
         document.querySelectorAll(".wf-menu").forEach((menu) => {
           if (!menu.contains(event.target)) menu.open = false;
         });
       });

