         create: jest.fn(async ({ data }: any) => ({
           id: resultId,
           ...data,
           reportedValue: new Prisma.Decimal(data.reportedValue),
         })),
       },
       taskVerification: {
         create: jest.fn(async ({ data }: any) => ({
           id: 'verification-id',
           ...data,
           verifier: { id: actor.id, username: 'reviewer', displayName: 'Reviewer' },
         })),
       },
     };
     prisma = {
       plan: { findFirst: jest.fn(async () => plan()) },
       task: {
