 function parseArgs(argv) {
   const options = { url: "", widths: defaultWidths, out: "", isDark: false, waitMs: 800, dpr: 1, playwrightDir: "", sweep: null, wireframeUrl: "", isQuick: false, isStress: false, dynamicWidths: null, storageState: "", isAuthenticated: false };
   const rest = [...argv];

   while (rest.length > 0) {
     const arg = rest.shift();

     if (arg === "--widths") options.widths = rest.shift().split(",").map(Number);
     else if (arg === "--sweep") {
       const [from, to, step] = /^\d+,\d+(,\d+)?$/.test(rest[0] ?? "") ? rest.shift().split(",").map(Number) : defaultSweep;
       options.sweep = { from: Math.max(from, to), to: Math.min(from, to), step: step || defaultSweep[2] };
     }
     else if (arg === "--out") options.out = rest.shift();
     else if (arg === "--dark") options.isDark = true;
     else if (arg === "--wait") options.waitMs = Number(rest.shift());
     else if (arg === "--dpr") options.dpr = Number(rest.shift());
     else if (arg === "--pw") options.playwrightDir = rest.shift();
     else if (arg === "--storage-state") options.storageState = rest.shift();
     else if (arg === "--login") options.isAuthenticated = true;
     else if (arg === "--wireframe") options.wireframeUrl = rest.shift();
     else if (arg === "--quick") options.isQuick = true;
     else if (arg === "--stress") options.isStress = true;
     else if (arg === "--dynamic-widths") {
       const value = rest.shift() ?? "";
       options.dynamicWidths = new Set(value === "none" ? [] : value.split(",").map(Number));
     }
     else if (!arg.startsWith("--")) options.url = arg;
   }

   // Wireframe ở Khổ Mobile chỉ là iframe 375: probe không đo được bên trong, chỉ báo "iframe lòi ra", và
   // bản thiết kế tràn ngang trong khung lọt qua (đo 12/10/2026). Đo thẳng trang ở khổ desktop, ở 375 media
   // query chạy y như trong khung.
   if (/[?&]kho=mobile\b/.test(options.url) && !/[?&]frame=/.test(options.url)) {
     options.url = options.url.replace(/([?&]kho=)mobile\b/, "$1desktop");
     console.log(`Link wireframe Khổ Mobile là iframe, đo thẳng trang: ${options.url}`);
   }

   if (!options.out) options.out = join(tmpdir(), `evon-probe-${Date.now()}`);
   if (options.isStress && !argv.includes("--widths")) options.widths = stressWidths;
   if (options.isQuick || options.isStress) options.dynamicWidths = new Set();
   if (!options.dynamicWidths) options.dynamicWidths = pickDefaultDynamicWidths(options.widths);

   return options;
