     if (!plan) throw new NotFoundException({ code: 'PLAN_NOT_FOUND' });

     const tasks = await this.prisma.task.findMany({
       where: { planId },
       orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
       include: taskInclude,
     });
