   ) {
     if (branchIds.length === 0) {
       await this.access.assertPermission(actorId, permission, AccessScope.ALL);
       return;
     }
     for (const branchId of branchIds) {
       await this.access.assertResourceAccess(actorId, permission, undefined, {
         ownerId,
         assigneeId: ownerId,
         branchId,
       });
     }
   }

